Given an array arr[] and an integer k, return the count of distinct numbers in all windows of size k. Examples: Input: arr[] = [1, 2, 1, 3, 4, 2, 3], k = 4Output: [3, 4, 4, 3]Explanation: First window is [1, 2, 1, 3], count of distinct numbers is 3.                       Second window is [2, 1, 3, 4] count of distinct numbers is 4.                       Third window is [1, 3, 4, 2] count of distinct numbers is 4.                       Fourth window is [3, 4, 2, 3] count of distinct numbers is 3.Input: arr[] = [4, 1, 1], k = 2Output: [2, 1]Explanation: First window is [4, 1], count of distinct numbers is 2.                       Second window is [1, 1], count of distinct numbers is 1. Try It YourselfTable of Content[Naive Approach] Traversal and Hashing - O(n × k) Time and O(1) Space[Expected Approach] Sliding Window and Hashing - O(n) Time and O(k) Space[Naive Approach] Traversal and Hashing - O(n × k) Time and O(1) SpaceTraverse the given array considering every window of size k in it and keep a count on the distinct elements of the window.
            C++

    #include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

vector<int> countDistinct(vector<int> &arr, int k) {
    int n = arr.size();  
    vector<int> res;

    // Iterate over every window
    for (int i = 0; i <= n - k; i++) {

        // Hash Set to count unique elements
        unordered_set<int> st;
        for(int j = i; j < i + k; j++)
        	st.insert(arr[j]);

        // Size of set denotes the number of unique elements
        // in the window
        res.push_back(st.size());
    }
    return res;
}

int main() {
    vector<int> arr = {1, 2, 1, 3, 4, 2, 3};
    int k = 4;

    vector<int> res = countDistinct(arr, k);
    for(int ele: res)
        cout << ele << " ";
    return 0;
}


